// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        c.getTokens{value: 0}();
        // After getTokens, if toGive > 0 (which is guaranteed if value > 0 and totalRemaining > 0),
        // the reference sets blacklist[caller] = true.
        // We check that the caller is blacklisted. In the mutant, the blacklist assignment is deleted.
        assertTrue(c.blacklist(caller));
    }
}

